// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {keepMyEther} from "../src/keepMyEther.sol";

contract InvMutTest is Test {
    keepMyEther c;
    function setUp() public { c = new keepMyEther(); }

    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(actor != address(0) && actor != address(c));
        amount = bound(amount, 1, 100 ether);

        Attacker attacker = new Attacker(c);

        vm.deal(actor, amount);
        vm.prank(actor);
        (bool ok,) = address(c).call{value: amount}("");
        require(ok, "deposit failed");

        uint256 sumBefore = c.balances(actor) + c.balances(address(attacker));

        vm.deal(address(attacker), amount);
        vm.prank(address(attacker));
        (bool ok2,) = address(c).call{value: amount}("");
        require(ok2, "attacker deposit failed");

        vm.prank(address(attacker));
        try c.withdraw() { } catch { }

        uint256 sumAfter = c.balances(actor) + c.balances(address(attacker));

        assertTrue(sumAfter == address(c).balance);
    }
}

contract Attacker {
    keepMyEther public target;
    constructor(keepMyEther _target) { target = _target; }

    receive() external payable {
        try target.withdraw() { } catch { }
    }
}
